<script setup>
import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {getMyRefunds} from '../../api/refund'
const router=useRouter(),records=ref([]),total=ref(0),page=ref(1),status=ref(''),loading=ref(false)
const load=async()=>{loading.value=true;try{const d=(await getMyRefunds({refundStatus:status.value||undefined,page:page.value,size:10})).data;records.value=d.records;total.value=d.total}finally{loading.value=false}};const filter=()=>{page.value=1;load()};onMounted(load)
</script>
<template><el-card><template #header><div class="head"><b>我的退票</b><el-radio-group v-model="status" @change="filter"><el-radio-button value="">全部</el-radio-button><el-radio-button value="PENDING">待审核</el-radio-button><el-radio-button value="APPROVED">已通过</el-radio-button><el-radio-button value="REJECTED">已驳回</el-radio-button></el-radio-group></div></template><el-table :data="records" v-loading="loading" empty-text="暂无退票记录"><el-table-column prop="refundNo" label="退款编号" min-width="220"/><el-table-column prop="orderNo" label="订单号" min-width="220"/><el-table-column label="比赛" min-width="190"><template #default="{row}">{{row.homeClubName}} vs {{row.awayClubName}}</template></el-table-column><el-table-column label="金额"><template #default="{row}">{{$formatMoney(row.refundAmount)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><StatusTag :value="row.refundStatus"/></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="router.push(`/user/refunds/${row.refundId}`)">详情</el-button></template></el-table-column></el-table><el-pagination v-if="total>10" v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/></el-card></template>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
